<script lang="ts">
  import FeedbackAdmin from './FeedbackAdmin.svelte';
  import NumberingSettings from './NumberingSettings.svelte';import {page} from '$app/state';import AiUsage from './AiUsage.svelte';import {onMount} from 'svelte';import {refreshAll,goto} from '$app/navigation';import {command,request,permitted,RequestError} from '#lib/client/api.ts';import type {AppData,Row,Field} from '#lib/client/types.ts';import FieldInput from './FieldInput.svelte';import Icon from './Icon.svelte';import Status from './Status.svelte';import UserManagement from './UserManagement.svelte';import Privacy from './Privacy.svelte';import IntegrationSettings from './IntegrationSettings.svelte';import Account from './Account.svelte';
  let {data}:{data:AppData}=$props();const requestedTab=$derived(page.url.searchParams.get('tab'));const settingsTabs=$derived([{id:'company',label:'Betrieb',permission:'admin'},{id:'finance',label:'Buchhaltung',permission:'admin'},{id:'numbering',label:'Nummernkreise',permission:'admin'},{id:'bank',label:'Bankverbindung',permission:'finance.bank.manage'},{id:'integrations',label:'Integrationen',permission:'admin.integrations'},{id:'usage',label:'KI-Verbrauch',permission:'admin.integrations'},{id:'feedback',label:'Rückmeldungen',permission:'admin'},{id:'approvals',label:'Fachliche Freigaben',permission:'admin'},{id:'modules',label:'Module',permission:'admin'},{id:'users',label:'Zugänge & Rollen',permission:'admin'},{id:'privacy',label:'Datenschutz',permission:'admin'},{id:'account',label:'Mein Zugang',permission:''}].filter(item=>(item.id!=='feedback'||data.context?.role==='SuperAdmin')&&(item.id==='account'||data.path!=='account'&&permitted(data,item.permission))));const tab=$derived(data.path==='account'?'account':settingsTabs.some(item=>item.id===requestedTab)?requestedTab!:permitted(data,'admin')?'company':'account');let values:Row=$state({});let busy=$state(false);let error=$state('');let notice=$state('');let fieldErrors:Record<string,string>=$state({});let password=$state('');let confirmCompany=$state(false);let approvalStatement=$state('');let approvals:Row=$state({});let moduleName=$state('crm');let moduleEnabled=$state(true);let moduleReason=$state('');
  const editable=$derived(permitted(data,'admin'));const bankEditable=$derived(permitted(data,'finance.bank.manage'));
  const companyFields:Field[]=[{key:'company_name',label:'Freigegebene Firmierung',type:'text',required:true},{key:'street',label:'Straße und Hausnummer',type:'text',required:true},{key:'postal_code',label:'Postleitzahl',type:'text',required:true},{key:'city',label:'Ort',type:'text',required:true},{key:'country',label:'Land (Ländercode)',type:'text',required:true},{key:'register_number',label:'Registerangabe',type:'text'},{key:'vat_id',label:'Umsatzsteuer-ID',type:'text'},{key:'tax_number',label:'Steuernummer',type:'text'}];
  const financeFields:Field[]=[{key:'previous_year_turnover',label:'Bestätigter Vorjahresumsatz · EUR',type:'money'},{key:'turnover_year',label:'Zugehöriges Geschäftsjahr',type:'number'},{key:'tax_profile',label:'Bestätigtes Steuerprofil',type:'select',options:[{value:'accrual',label:'Sollversteuerung'},{value:'cash',label:'Istversteuerung'},{value:'small_business',label:'Kleinunternehmer · ausdrücklich bestätigt'}]},{key:'datev_advisor',label:'DATEV-Beraternummer',type:'text'},{key:'datev_client',label:'DATEV-Mandantennummer',type:'text'},{key:'datev_account_length',label:'Bestätigte Kontenlänge',type:'number'},{key:'datev_mapping',label:'Freigegebene Kontenzuordnung',type:'textarea'}];
  const bankFields:Field[]=[{key:'iban',label:'IBAN',type:'text',required:true},{key:'bic',label:'BIC',type:'text'},{key:'bank_holder',label:'Kontoinhaber',type:'text',required:true}];
  const source=$derived(data.settings?.legalEntity||data.settings?.legal_entity||data.settings||{});
  onMount(()=>{approvals={billing_approved:!!source.billing_approved,tax_approved:!!source.tax_approved,contract_approved:!!source.contract_approved,datev_approved:!!source.datev_approved};values=Object.fromEntries([...companyFields,...financeFields,...bankFields].map(f=>[f.key,source[f.key]!==null&&typeof source[f.key]==='object'?JSON.stringify(source[f.key],null,2):source[f.key]??'']));});
  async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';fieldErrors={};try{if(tab==='finance'){const amount=String(values.previous_year_turnover??'').trim(),year=String(values.turnover_year??'').trim();if(!!amount!==!!year)throw new Error('Bestätigten Vorjahresumsatz und zugehöriges Geschäftsjahr gemeinsam eintragen oder beide Angaben leeren.');if(year&&(!/^\d{4}$/.test(year)||Number(year)<1900||Number(year)>new Date().getFullYear()))throw new Error('Das bestätigte Geschäftsjahr als vierstellige Jahreszahl bis zum laufenden Jahr eingeben.');if(amount&&(!/^\d+(?:[,.]\d+)?$/.test(amount)||Number(amount.replace(',','.'))<0))throw new Error('Den bestätigten Umsatz als nichtnegativen EUR-Betrag eingeben.');}if(tab==='bank')await request('/api/v1/reauth',{password});const fields=tab==='company'?companyFields:tab==='bank'?bankFields:financeFields;const payload=Object.fromEntries(fields.map(f=>[f.key,['previous_year_turnover','turnover_year','datev_account_length'].includes(f.key)&&values[f.key]===''?null:values[f.key]]));await command('settings.update',undefined,payload,source.version);await refreshAll().catch(()=>{});notice='Die Betriebseinstellungen wurden gespeichert.';password='';}catch(e){error=e instanceof Error?e.message:'Speichern fehlgeschlagen.';if(e instanceof RequestError)fieldErrors=e.fields;}finally{busy=false;}}
  async function saveApprovals(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});await command('settings.update',undefined,{...approvals,approval_statement:approvalStatement},source.version);notice='Die fachliche Freigabeentscheidung wurde mit dem Nachweis gespeichert.';approvalStatement='';password='';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Freigabeentscheidung fehlgeschlagen.';}finally{busy=false;}}
  async function saveModule(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});await command('administration.module.update',undefined,{module:moduleName,enabled:moduleEnabled,reason:moduleReason});password='';moduleReason='';notice='Die Moduleinstellung wurde gespeichert.';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Moduleinstellung fehlgeschlagen.';}finally{busy=false;}}
</script>
<div class="page-heading"><div><h1>{data.path==='account'?'Mein persönlicher Zugang.':'Ein guter Rahmen.'}</h1><p>{data.path==='account'?'Profil prüfen, Passphrase ändern und angemeldete Geräte verwalten.':'Bestätigte Stammdaten, sichere Zugänge und ein transparenter Integrationsstatus.'}</p></div>{#if editable}<a class="btn" href="/rules"><Icon name="file" size={16}/>Regeln & Freigaben</a>{/if}</div>
<div class="settings-layout" class:account-layout={data.path==='account'}><div class="field settings-selector"><label for="settings-section">Einstellungsbereich</label><select id="settings-section" value={tab} onchange={event=>goto('/settings?tab='+event.currentTarget.value)}>{#each settingsTabs as item}<option value={item.id}>{item.label}</option>{/each}</select></div><nav class="tabs settings-tabs" aria-label="Einstellungsbereiche">{#each settingsTabs as item}<button class="tab" class:active={tab===item.id} aria-current={tab===item.id?'page':undefined} onclick={()=>goto('/settings?tab='+item.id)}>{item.label}</button>{/each}</nav><div class="settings-content">
{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}
{#if tab==='feedback'&&data.context?.role==='SuperAdmin'}<FeedbackAdmin {data}/>{:else if tab==='numbering'&&editable}<NumberingSettings {data}/>{:else if tab==='usage'&&permitted(data,'admin.integrations')}<AiUsage {data} configured={!!data.integrations?.ai?.available}/>{:else if tab==='integrations'}<div class="notice info mb"><div><strong>App-Messwerte und Anbieter-Kontingente</strong><p>Die Anzeigen unten erfassen Vorgänge dieser Suite. Vercel, Neon und OpenAI führen eigene Kontingente; andere Projekte können diese mitnutzen. Die Anbieterübersichten bleiben maßgeblich. Im <a class="text-link" href="https://vercel.com/dashboard" target="_blank" rel="noreferrer">Vercel-Dashboard</a> wählen Sie das richtige Team und anschließend „Usage“. <a class="text-link" href="https://vercel.com/docs/pricing/manage-and-optimize-usage" target="_blank" rel="noreferrer">Verbrauchsübersicht finden</a>. Es findet keine laufende Cloud-Abfrage statt.</p></div></div><div class="settings-grid"><section class="panel"><header class="panel-header"><h2>Verbundene Dienste</h2></header><div class="panel-body">{#each Object.entries(data.integrations||{}) as [key,integration]}<div class="integration-row"><div><h3>{({database:'PostgreSQL-Datenbank',storage:'Privater Dateispeicher',blob:'Privater Dateispeicher',archive:'Revisionsgebundenes Archiv',ai:'OpenAI-Assistent',openai:'OpenAI',smtp:'E-Mail-Versand',mail:'E-Mail-Versand',queue:'Hintergrundverarbeitung',malware:'Dateiprüfung',scanner:'Dateiprüfung',einvoice:'E-Rechnungsvalidierung',datev:'DATEV-Verfahren',renderer:'Exaktes 3D-Rendering'} as Record<string,string>)[key]||key}</h3><p>{integration.message}</p></div><Status value={integration.available?'available':'blocked'}/></div>{/each}{#if !Object.keys(data.integrations||{}).length}<p class="small">Es liegen noch keine bestätigten Integrationszustände vor.</p>{/if}</div></section><aside class="stack"><section class="panel"><header class="panel-header"><h2>Einrichtung vervollständigen</h2></header><div class="panel-body"><p class="small">E-Mail und OpenAI können berechtigte Administratoren unten einrichten. Der angezeigte Dienststatus beschreibt die tatsächlich bestätigte Verfügbarkeit.</p><a class="btn full mt" href="/jobs">Verarbeitung & Fehler prüfen<Icon name="arrow" size={16}/></a></div></section><section class="panel"><header class="panel-header"><h2>Fachliche Freigaben</h2></header><div class="panel-body"><p class="small">Rechnungsausstellung und Fertigung benötigen bestätigte Betriebseinstellungen, geeignete Prüfprofile und die erforderlichen Nachweise.</p><a class="text-link mt" href="/rules">Versionierte Regeln prüfen<Icon name="arrow" size={15}/></a></div></section></aside></div>
<IntegrationSettings {data}/>{:else if tab==='approvals'}<section class="panel"><header class="panel-header"><h2>Fachliche Entscheidungen dokumentieren</h2></header><form class="panel-body" onsubmit={saveApprovals}><p class="small mb">Jede Freigabe benötigt eine verantwortliche Person und einen konkreten Nachweis. Technische Archiv- und E-Rechnungsgates bleiben eigenständige Prüfungen.</p>{#each [{key:'billing_approved',label:'Ausstellerdaten und Rechnungsverfahren fachlich freigegeben'},{key:'tax_approved',label:'Steuerprofil und Buchungsgrundlagen durch zuständige Fachperson freigegeben'},{key:'contract_approved',label:'Vertragsmuster und einschlägige Pflichtinformationen fachlich freigegeben'},{key:'datev_approved',label:'DATEV-Zuordnung und Übergabeverfahren von der Kanzlei freigegeben'}] as approval}<label class="check-field mb"><input type="checkbox" bind:checked={approvals[approval.key]}/><span>{approval.label}</span></label>{/each}<div class="field"><label for="approval-statement">Fachliche Zuständigkeit und Nachweis *</label><textarea id="approval-statement" bind:value={approvalStatement} required minlength="16" placeholder="Prüfende Person, Datum, geprüfter Geltungsbereich und Dokumentreferenz"></textarea></div><div class="field mt"><label for="approval-password">Ihr eigenes Suite-Passwort bestätigen *</label><input id="approval-password" type="password" bind:value={password} autocomplete="current-password" required/><span class="field-help">Bestätigt diese dokumentierte Freigabe mit Ihrem persönlichen Zugang.</span></div><button class="btn primary mt" disabled={busy}>Freigabeentscheidung speichern</button></form></section>{:else if tab==='modules'}<section class="panel"><header class="panel-header"><h2>Arbeitsbereiche im Betrieb</h2></header><form class="panel-body" onsubmit={saveModule}><div class="field-grid"><div class="field"><label for="module-name">Modul *</label><select id="module-name" bind:value={moduleName}>{#each [{key:'crm',label:'Kunden & Anfragen'},{key:'sales',label:'Vertrieb'},{key:'orders',label:'Aufträge'},{key:'billing',label:'Rechnungen'},{key:'finance',label:'Finanzen'},{key:'purchasing',label:'Einkauf'},{key:'catalog',label:'Katalog'},{key:'inventory',label:'Lager'},{key:'planning',label:'Planung'},{key:'dispatch',label:'Disposition'},{key:'time',label:'Zeiterfassung'},{key:'documents',label:'Dokumente'},{key:'imports',label:'Datenübernahme'},{key:'reports',label:'Auswertungen'}] as module}<option value={module.key}>{module.label}</option>{/each}</select></div><div class="field"><label for="module-enabled">Gewünschter Zustand *</label><select id="module-enabled" bind:value={moduleEnabled}><option value={true}>Aktiviert</option><option value={false}>Deaktiviert</option></select></div><div class="field full"><label for="module-reason">Begründung *</label><textarea id="module-reason" bind:value={moduleReason} required minlength="3"></textarea></div><div class="field full"><label for="module-password">Eigenes Passwort bestätigen *</label><input id="module-password" type="password" bind:value={password} autocomplete="current-password" required/></div></div><button class="btn primary mt" disabled={busy}>Moduleinstellung bestätigen</button><p class="field-help mt">Historische Daten bleiben erhalten. Das Abschalten eines Moduls ersetzt keine Lösch- oder Aufbewahrungsentscheidung.</p></form></section>{:else if tab==='privacy'}<Privacy {data}/>{:else if tab==='users'}<UserManagement {data}/>{:else if tab==='account'||data.path==='account'||!editable}<Account {data}/>
{:else}<div class="settings-grid"><section class="panel"><header class="panel-header"><h2>{tab==='company'?'Firmierung & Anschrift':tab==='bank'?'Bestätigte Bankdaten':'Buchhaltungsprofil'}</h2>{#if !editable&&tab!=='bank'}<Status value="blocked"/>{/if}</header><form onsubmit={save} style="display:contents"><fieldset class="panel-body" disabled={!(tab==='bank'?bankEditable:editable)||busy} style="border:0;margin:0;min-width:0"><div class="field-grid">{#each tab==='company'?companyFields:tab==='bank'?bankFields:financeFields as field}<FieldInput {field} bind:value={values[field.key]} error={fieldErrors[field.key]} prefix="settings"/>{/each}{#if tab==='bank'}<div class="field full"><label for="bank-password">Eigenes Passwort erneut eingeben *</label><input id="bank-password" type="password" autocomplete="current-password" bind:value={password} required/><span class="field-help">Die Änderung wird erst nach erneuter Authentifizierung übernommen. Bestehende Belege behalten ihren eingefrorenen Bankstand.</span></div>{:else if tab==='company'}<label class="check-field" style="grid-column:1/-1"><input type="checkbox" bind:checked={confirmCompany}/><span>Die angegebene Firmierung und Anschrift wurden betrieblich geprüft.</span></label>{/if}</div></fieldset><footer class="panel-footer"><span class="small muted">{tab==='bank'?'Änderung mit zusätzlichem Nachweis':editable?'Versionierte Betriebskonfiguration':'Für Änderungen wird das Verwaltungsrecht benötigt.'}</span><button class="btn primary" type="submit" disabled={!(tab==='bank'?bankEditable:editable)||busy||(tab==='company'&&!confirmCompany)}>{busy?'Wird gespeichert …':'Einstellungen speichern'}</button></footer></form></section><aside class="stack"><section class="panel"><header class="panel-header"><h2>Freigabestand</h2></header><div class="panel-body"><dl class="definition-list" style="grid-template-columns:1fr">{#each [{key:'billing_approved',label:'Rechnungsausstellung'},{key:'tax_approved',label:'Steuerprofil'},{key:'contract_approved',label:'Vertragsprofil'},{key:'datev_approved',label:'DATEV-Verfahren'}] as approval}<div><dt>{approval.label}</dt><dd><Status value={source[approval.key]?'approved':'needs_review'}/></dd></div>{/each}</dl></div></section><section class="panel"><header class="panel-header"><h2>Nachvollziehbare Grundlagen</h2></header><div class="panel-body"><p class="small">Technische Integrationen und fachliche Freigaben werden getrennt geprüft. Hinterlegen Sie Steuerregeln, Vertragsmuster und Zuständigkeiten mit einer belegten Quelle.</p><div class="quick-links" style="padding:10px 0 0"><a class="quick-link" href="/rules"><Icon name="file" size={16}/>Regeln verwalten<Icon name="arrow" size={15}/></a><a class="quick-link" href="/audit"><Icon name="clock" size={16}/>Nachweisprotokoll<Icon name="arrow" size={15}/></a><a class="quick-link" href="/team"><Icon name="users" size={16}/>Team verwalten<Icon name="arrow" size={15}/></a></div></div></section></aside></div>{/if}

</div></div>
<style>
.settings-layout{display:grid;grid-template-columns:188px minmax(0,1fr);gap:27px;align-items:start}.settings-selector{display:none}.settings-tabs{display:flex;flex-direction:column;align-items:stretch;gap:3px;width:100%;margin:0;padding:0;border:0;border-radius:0;background:transparent;overflow:visible}.settings-tabs .tab{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:41px;padding:10px 12px;border:0;border-radius:8px;text-align:left;font-size:12px;line-height:1.6;white-space:normal}.settings-tabs .tab.active{color:var(--forest);background:var(--accent-wash);box-shadow:none}.settings-tabs .tab:hover{background:var(--wash)}.settings-content{min-width:0}.settings-layout.account-layout{display:block}.account-layout .settings-tabs,.account-layout .settings-selector{display:none}@media(max-width:1250px){.settings-content :global(.settings-grid){grid-template-columns:1fr}}@media(max-width:1000px){.settings-layout{grid-template-columns:165px minmax(0,1fr);gap:20px}.settings-tabs .tab{padding:10px;font-size:12px}}@media(max-width:760px){.settings-layout{display:block}.settings-selector{display:flex;margin-bottom:22px}.settings-tabs{display:none}.settings-selector select{width:100%;min-height:48px}.settings-content{width:100%}}
</style>
